import React, { useState, useEffect, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { SetupStep } from './components/SetupStep';
import { Dashboard } from './components/Dashboard';
import { ProcessingLog } from './components/ProcessingLog';
import { TaxonomyReview } from './components/TaxonomyReview';
import { OpenAIService } from './services/openai';
import { GeminiService } from './services/gemini';
import { extractTextFromPdf } from './services/pdf';
import { performClustering } from './services/clustering';
import { listPdfFiles, downloadFile } from './services/drive';
import { savePapersToDB, loadPapersFromDB, clearPapersDB } from './services/storage';
import { ProcessingStatus, Paper, AppPhase, Taxonomy, BroadCategory, MidCategory, FineCategory, SystemConfig } from './types';
import { LogOut, RefreshCw } from 'lucide-react';
import { METADATA_EXTRACTION_PROMPT, METADATA_SCHEMA } from './constants';
// Interface for the object coming from SetupStep
interface SetupConfig {
    apiKey: string;
    geminiApiKey?: string;
    googleClientId?: string;
    googleToken?: string;
    folderId?: string;
}

function App() {
  // State
  const [phase, setPhase] = useState<AppPhase>('setup');
  const [config, setConfig] = useState<SystemConfig | null>(null);
  const [papers, setPapers] = useState<Paper[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [status, setStatus] = useState<ProcessingStatus>(ProcessingStatus.PENDING);
  const [progress, setProgress] = useState(0);
  const [taxonomy, setTaxonomy] = useState<Taxonomy | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);

  // Batch API specific state
  const [useBatchApi, setUseBatchApi] = useState(false);
  const [batchStatus, setBatchStatus] = useState<any>(null);

  // Services & Refs
  const [aiService, setAiService] = useState<OpenAIService | null>(null);
  const [geminiService, setGeminiService] = useState<GeminiService | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);
  const batchPollInterval = useRef<number | null>(null);

  // --- Persistence Logic ---
  useEffect(() => {
    const loadState = async () => {
        try {
            const savedConfig = localStorage.getItem('researchai_config');
            const savedTaxonomy = localStorage.getItem('researchai_taxonomy');

            if (savedConfig) {
                const parsedConfig = JSON.parse(savedConfig);
                setConfig(parsedConfig);
                setUseBatchApi(!!parsedConfig.useBatchApi);
                setAiService(new OpenAIService(parsedConfig.openaiApiKey));
                if (parsedConfig.geminiApiKey) {
                    setGeminiService(new GeminiService(parsedConfig.geminiApiKey));
                }

                // Resume batch polling if needed
                if (parsedConfig.activeBatchId) {
                    setBatchStatus({ id: parsedConfig.activeBatchId, status: 'resuming...' });
                    pollBatch(parsedConfig.activeBatchId, parsedConfig.openaiApiKey);
                }

                setPhase('dashboard');
                addLog('Restored session from local storage.');
            }

            // Load papers from IndexedDB
            const savedPapers = await loadPapersFromDB();
            if (savedPapers && savedPapers.length > 0) {

                // Sanitize statuses for interrupted jobs
                const sanitizedPapers = savedPapers.map(p => {
                    if (p.status === ProcessingStatus.EXTRACTING) {
                        return { ...p, status: ProcessingStatus.PENDING };
                    }
                    if (p.status === ProcessingStatus.EMBEDDING && (!p.embedding || p.embedding.length === 0)) {
                        return { ...p, status: ProcessingStatus.EXTRACTED };
                    }
                    if (p.status === ProcessingStatus.CLASSIFYING) {
                        return { ...p, status: ProcessingStatus.EMBEDDING };
                    }
                    return p;
                });
                setPapers(sanitizedPapers);
            }

            if (savedTaxonomy) {
                setTaxonomy(JSON.parse(savedTaxonomy));
            }
        } catch (e) {
            console.error("Failed to load state", e);
            addLog(`Error loading saved state: ${e}`);
        } finally {
            setIsLoaded(true);
        }
    };
    loadState();
  }, []);

  // Clean up interval and abort controller on unmount
  useEffect(() => {
    return () => {
        if (batchPollInterval.current) {
            clearInterval(batchPollInterval.current);
        }
        if (abortControllerRef.current) {
            abortControllerRef.current.abort();
        }
    };
  }, []);

  // Save Config
  useEffect(() => {
      if (!isLoaded) return;
      if (config) {
          const configToSave = { ...config, useBatchApi };
          localStorage.setItem('researchai_config', JSON.stringify(configToSave));
      }
  }, [config, isLoaded, useBatchApi]);

  // Save Papers (IndexedDB with Debounce)
  useEffect(() => {
      if (!isLoaded) return;

      const timeoutId = setTimeout(() => {
          savePapersToDB(papers).catch(err => {
              console.error("Failed to save papers to DB:", err);
          });
      }, 1000); 

      return () => clearTimeout(timeoutId);
  }, [papers, isLoaded]);

  // Save Taxonomy
  useEffect(() => {
      if (!isLoaded) return;
      if (taxonomy) {
          try {
            localStorage.setItem('researchai_taxonomy', JSON.stringify(taxonomy));
          } catch (e) {
            console.warn("Taxonomy too large for localStorage", e);
          }
      }
  }, [taxonomy, isLoaded]);

  const handleResetSystem = async () => {
      if (confirm("Are you sure? This will clear all data and API keys.")) {
          localStorage.removeItem('researchai_config');
          localStorage.removeItem('researchai_papers');
          localStorage.removeItem('researchai_taxonomy');
          await clearPapersDB();
          window.location.reload();
      }
  };

  const addLog = (msg: string) => {
      setLogs(prev => {
          const newLogs = [...prev, msg];
          if (newLogs.length > 1000) return newLogs.slice(-1000);
          return newLogs;
      });
  };

  const handleStop = () => {
      if (abortControllerRef.current) {
          abortControllerRef.current.abort();
          addLog(">>> STOPPING PROCESS...");
      }
  };

  const handleSetupComplete = (setupCfg: SetupConfig) => {
    const systemConfig: SystemConfig = {
        openaiApiKey: setupCfg.apiKey,
        geminiApiKey: setupCfg.geminiApiKey,
        googleClientId: setupCfg.googleClientId,
        googleToken: setupCfg.googleToken,
        folderId: setupCfg.folderId,
        maxConcurrent: 5
    };

    setConfig(systemConfig);
    setAiService(new OpenAIService(systemConfig.openaiApiKey));
    if (systemConfig.geminiApiKey) {
        setGeminiService(new GeminiService(systemConfig.geminiApiKey));
    }
    setPhase('dashboard');
    addLog('System initialized.');

    if (systemConfig.folderId) {
        addLog(`Drive Folder configured: ${systemConfig.folderId}`);
        addLog('Click "Sync with Drive" to import papers.');
    } else {
        addLog('Ready to process local papers.');
    }
  };

  const refreshDriveToken = () => {
      if (!config) return;

      if (config.googleClientId === 'manual-token' || !config.googleClientId) {
          const newToken = prompt("Enter new Google Access Token:");
          if (newToken) {
              setConfig(prev => prev ? { ...prev, googleToken: newToken } : null);
              addLog("Token manually updated.");
          }
          return;
      }

      if (!window.google) {
          addLog("Google Identity Services script not loaded.");
          return;
      }

      try {
          const client = window.google.accounts.oauth2.initTokenClient({
              client_id: config.googleClientId,
              scope: 'https://www.googleapis.com/auth/drive.readonly',
              callback: (response: any) => {
                  if (response.access_token) {
                      setConfig(prev => prev ? { ...prev, googleToken: response.access_token } : null);
                      addLog("Drive token refreshed successfully.");
                  }
              },
          });
          client.requestAccessToken();
      } catch (e) {
          console.error(e);
          addLog("Failed to initiate token refresh.");
      }
  };

  const handleAddFiles = (files: FileList) => {
    const newPapers: Paper[] = Array.from(files).map(f => ({
      id: uuidv4(),
      filename: f.name,
      status: ProcessingStatus.PENDING,
      fileObj: f
    }));
    setPapers(prev => [...prev, ...newPapers]);
    addLog(`Added ${newPapers.length} local files to queue.`);
  };

  const handleGenerateImage = async (paperId: string) => {
    if (!geminiService) {
        alert("Gemini API Key is required for Image Generation. Please reset system and configure it.");
        return;
    }

    const paperIndex = papers.findIndex(p => p.id === paperId);
    if (paperIndex === -1) return;
    const paper = papers[paperIndex];

    try {
        addLog(`Generating image for ${paper.filename}...`);
        const imageUrl = await geminiService.generatePaperImage(
            paper.title || paper.filename, 
            paper.summary || paper.abstract || "Scientific research paper."
        );

        setPapers(prev => prev.map(p => p.id === paperId ? { ...p, generated_image: imageUrl } : p));
        addLog(`Image generated successfully for ${paper.filename}`);
    } catch (e: any) {
        console.error(e);
        addLog(`Failed to generate image for ${paper.filename}: ${e.message}`);
        alert(`Image generation failed: ${e.message}`);
    }
  };

  const scanDrive = async () => {
      if (!config?.googleToken || !config?.folderId) return;

      setIsSyncing(true);
      addLog("Scanning Google Drive folder...");
      try {
          const files = await listPdfFiles(config.googleToken, config.folderId);
          const newPapers: Paper[] = files.map(f => ({
              id: uuidv4(),
              filename: f.name,
              status: ProcessingStatus.PENDING,
              driveId: f.id
          }));

          const currentIds = new Set(papers.map(p => p.driveId).filter(Boolean));
          const uniquePapers = newPapers.filter(p => !currentIds.has(p.driveId));

          if (uniquePapers.length > 0) {
            setPapers(prev => [...prev, ...uniquePapers]);
            addLog(`Found ${uniquePapers.length} new PDFs in Drive.`);
          } else {
              addLog("No new PDFs found.");
          }
      } catch (e) {
          addLog(`Error scanning drive: ${e}`);
      } finally {
          setIsSyncing(false);
      }
  };

  const handleReprocessPaper = async (paperId: string) => {
    if (!aiService) return;

    const paperIndex = papers.findIndex(p => p.id === paperId);
    if (paperIndex === -1) return;
    const paperObj = papers[paperIndex];

    addLog(`Reprocessing ${paperObj.filename}...`);
    setPapers(prev => prev.map(p => p.id === paperId ? { ...p, status: ProcessingStatus.EXTRACTING, error: undefined } : p));

    try {
        let text = paperObj.content_text;
        if (!text) {
             if (paperObj.driveId && config?.googleToken) {
                 const buffer = await downloadFile(config.googleToken, paperObj.driveId);
                 const blob = new Blob([buffer], { type: 'application/pdf' });
                 const file = new File([blob], paperObj.filename, { type: 'application/pdf' });
                 text = await extractTextFromPdf(file);
            } else if (paperObj.fileObj) {
                 // @ts-ignore
                 text = await extractTextFr

import React, { useRef, useState, useMemo } from 'react';
import { Paper, ProcessingStatus, Taxonomy } from '../types';
import { FileText, Activity, Layers, AlertCircle, Plus, RefreshCw, Download, RotateCw, Search, GitBranch, ArrowUp, ArrowDown, ArrowUpDown, Zap, Clock, Database, Play } from 'lucide-react';
import { PaperDetailsModal } from './PaperDetailsModal';
import { TaxonomyVisualizer } from './TaxonomyVisualizer';

interface DashboardProps {
  papers: Paper[];
  taxonomy?: Taxonomy | null;
  status: ProcessingStatus;
  onProcess: () => void;
  onProcessPartial: () => void;
  onAddFiles: (files: FileList) => void;
  onScanDrive?: () => void;
  isSyncing?: boolean;
  googleToken?: string;
  onReprocess?: (paperId: string) => void;
  onGenerateImage?: (paperId: string) => void;
  useBatchApi: boolean;
  onToggleBatchApi: (use: boolean) => void;
  batchStatus?: any;
  onCancelBatch?: () => void;
}

type SortField = 'filename' | 'title' | 'status' | 'broad_category' | 'mid_category' | 'fine_category' | 'publish_date';
type SortDirection = 'asc' | 'desc';

export const Dashboard: React.FC<DashboardProps> = ({ 
  papers, 
  taxonomy, 
  status, 
  onProcess, 
  onProcessPartial,
  onAddFiles, 
  onScanDrive, 
  isSyncing, 
  googleToken, 
  onReprocess, 
  onGenerateImage,
  useBatchApi,
  onToggleBatchApi,
  batchStatus,
  onCancelBatch
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [selectedPaperId, setSelectedPaperId] = useState<string | null>(null);
  const [showTaxonomyMap, setShowTaxonomyMap] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortField, setSortField] = useState<SortField>('filename');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  // Direct lookup to ensure we always have the latest state from App
  const selectedPaper = papers.find(p => p.id === selectedPaperId) || null;

  const stats = {
    total: papers.length,
    processed: papers.filter(p => p.status === ProcessingStatus.COMPLETED).length,
    failed: papers.filter(p => p.status === ProcessingStatus.FAILED).length,
    extractedOrReady: papers.filter(p => 
        [
            ProcessingStatus.EXTRACTED, 
            ProcessingStatus.EMBEDDING, 
            ProcessingStatus.CLUSTERING, 
            ProcessingStatus.REVIEW_WAIT, 
            ProcessingStatus.CLASSIFYING, 
            ProcessingStatus.COMPLETED,
            ProcessingStatus.BATCH_RUNNING
        ].includes(p.status)
    ).length
  };

  const processedPct = stats.total > 0 ? Math.round((stats.processed / stats.total) * 100) : 0;
  const extractedPct = stats.total > 0 ? Math.round((stats.extractedOrReady / stats.total) * 100) : 0;

  // Calculate if we have papers ready for the next phase (post-extraction)
  const readyForAnalysisCount = papers.filter(p => 
    p.status === ProcessingStatus.EXTRACTED || 
    (p.status === ProcessingStatus.EMBEDDING && (!p.embedding || p.embedding.length === 0))
  ).length;

  const handleSort = (field: SortField) => {
    if (sortField === field) {
        setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc');
    } else {
        setSortField(field);
        setSortDirection('asc');
    }
  };

  const filteredPapers = useMemo(() => {
    let result = papers;
    const query = searchQuery.toLowerCase().trim();

    // 1. Filter
    if (query) {
        const terms = query.split(/\s+/);
        result = papers.filter(p => {
            const searchableContent = [
                p.filename,
                p.title,
                p.publish_date,
                p.classification?.broad_category,
                p.classification?.mid_category,
                p.classification?.fine_category,
                p.authors?.join(' '),
            ].filter(Boolean).join(' ').toLowerCase();

            return terms.every(term => searchableContent.includes(term));
        });
    }

    // 2. Sort
    return [...result].sort((a, b) => {
        let valA = '';
        let valB = '';

        switch (sortField) {
            case 'filename':
                valA = a.filename || '';
                valB = b.filename || '';
                break;
            case 'title':
                valA = a.title || '';
                valB = b.title || '';
                break;
            case 'status':
                valA = a.status || '';
                valB = b.status || '';
                break;
            case 'publish_date':
                valA = a.publish_date || '';
                valB = b.publish_date || '';
                break;
            case 'broad_category':
                valA = a.classification?.broad_category || '';
                valB = b.classification?.broad_category || '';
                break;
            case 'mid_category':
                valA = a.classification?.mid_category || '';
                valB = b.classification?.mid_category || '';
                break;
            case 'fine_category':
                valA = a.classification?.fine_category || '';
                valB = b.classification?.fine_category || '';
                break;
        }

        const comparison = valA.localeCompare(valB, undefined, { numeric: true, sensitivity: 'base' });
        return sortDirection === 'asc' ? comparison : -comparison;
    });
  }, [papers, searchQuery, sortField, sortDirection]);

  const handleExportCSV = () => {
    const headers = [
        "ID", "Filename", "Title", "Authors", "Publish Date", "Status", 
        "Broad Category", "Mid Category", "Fine Category", "Reasoning", "Summary",
        "Drive ID", "Drive Link", "Embedding", "Generated Image Data"
    ];

    const rows = filteredPapers.map(p => [
        p.id,
        `"${(p.filename || '').replace(/"/g, '""')}"`,
        `"${(p.title || '').replace(/"/g, '""')}"`,
        `"${(p.authors?.join(', ') || '').replace(/"/g, '""')}"`,
        p.publish_date || '',
        p.status,
        `"${(p.classification?.broad_category || '').replace(/"/g, '""')}"`,
        `"${(p.classification?.mid_category || '').replace(/"/g, '""')}"`,
        `"${(p.classification?.fine_category || '').replace(/"/g, '""')}"`,
        `"${(p.classification?.reasoning || '').replace(/"/g, '""')}"`,
        `"${(p.summary || p.abstract || '').replace(/"/g, '""').slice(0, 2000)}"`,
        p.driveId || '',
        p.driveId ? `[local reference removed]` : '',
        p.embedding ? `"${JSON.stringify(p.embedding).replace(/"/g, '""')}"` : '',
        p.generated_image ? `"${p.generated_image.replace(/"/g, '""')}"` : ""
    ]);

    const csvContent = [
        headers.join(','),
        ...rows.map(r => r.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `research_papers_export_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const SortableHeader = ({ field, label }: { field: SortField, label: string }) => (
    <th 
        className="px-4 py-4 cursor-pointer hover:bg-slate-100 transition-colors select-none whitespace-nowrap group"
        onClick={() => handleSort(field)}
    >
        <div className="flex items-center gap-2">
            {label}
            <div className="text-slate-300 group-hover:text-blue-400">
                {sortField === field ? (
                    sortDirection === 'asc' ? <ArrowUp size={14} className="text-blue-600" /> : <ArrowDown size={14} className="text-blue-600" />
                ) : (
                    <ArrowUpDown size={14} />
                )}
            </div>
        </div>
    </th>
  );

  const isIdle = status !== ProcessingStatus.EXTRACTING && 
                 status !== ProcessingStatus.EMBEDDING && 
                 status !== ProcessingStatus.CLUSTERING && 
                 status !== ProcessingStatus.CLASSIFYING &&
                 status !== ProcessingStatus.BATCH_RUNNING;

  return (
    <div className="space-y-6">
      {/* Header Stats */}
      <div className="grid grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 text-slate-500 mb-2">
            <FileText size={18} /> <span className="text-sm font-medium">Total Papers</span>
          </div>
          <div className="text-2xl font-bold text-slate-900">{stats.total}</div>
        </div>

        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 text-green-600 mb-2">
            <Activity size={18} /> <span className="text-sm font-medium">Fully Processed</span>
          </div>
          <div className="flex items-end justify-between">
            <div className="text-2xl font-bold text-slate-900">{stats.processed}</div>
            <div className="text-xs font-bold text-green-600 mb-1">{processedPct}%</div>
          </div>
          <div className="w-full bg-slate-100 h-1.5 rounded-full mt-2 overflow-hidden">
             <div className="bg-green-500 h-full rounded-full" style={{width: `${processedPct}%`}}></div>
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 text-indigo-600 mb-2">
            <Layers size={18} /> <span className="text-sm font-medium">Extracted & Ready</span>
          </div>
          <div className="flex items-end justify-between">
            <div className="text-2xl font-bold text-slate-900">{stats.extractedOrReady}</div>
            <div className="text-xs font-bold text-indigo-600 mb-1">{extractedPct}%</div>
          </div>
           <div className="w-full bg-slate-100 h-1.5 rounded-full mt-2 overflow-hidden">
             <div className="bg-indigo-500 h-full rounded-full" style={{width: `${extractedPct}%`}}></div>
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 text-red-500 mb-2">
            <AlertCircle size={18} /> <span className="text-sm font-medium">Failures</span>
          </div>
          <div className="text-2xl font-bold text-slate-900">{stats.failed}</div>
          <div className="text-xs text-slate-400 mt-2">Require attention</div>
        </div>
      </div>

      {/* Batch Status Panel */}
      {batchStatus && (
          <div className="bg-slate-900 text-slate-200 p-4 rounded-xl shadow-sm border border-slate-800 flex items-center justify-between animate-in fade-in slide-in-from-top-4">
              <div className="flex items-center gap-4">
                  <div className="p-2 bg-blue-600/20 rounded-full text-blue-400">
                      {batchStatus.status === 'completed' ? <Database size={24} /> : <RefreshCw size={24} className="animate-spin" />}
                  </div>
                  <div>
                      <h3 className="font-bold text-white flex items-center gap-2">
                          Batch API Job {batchStatus.status === 'completed' ? 'Completed' : (batchStatus.status === 'cancelled' ? 'Cancelled' : 'Running')}
                          <span className={`text-xs font-normal px-2 py-0.5 rounded-full text-slate-300 uppercase
                              ${batchStatus.status === 'completed' ? 'bg-green-700' : 
                                batchStatus.status === 'failed' ? 'bg-red-700' :
                                batchStatus.status === 'cancelled' ? 'bg-amber-700' :
                                'bg-slate-700'}`}>
                              {batchStatus.status}
                          </span>
                      </h3>
                      <p className="text-sm text-slate-400">ID: <span className="font-mono">{batchStatus.i

import React, { useState, useMemo } from 'react';
import { Paper, ProcessingStatus } from '../types';
import { X, FileText, Users, Calendar, Tag, AlertTriangle, AlignLeft, CheckCircle, Clock, XCircle, Download, Loader2, Link, ExternalLink, Info, FileCode, Activity, Sparkles, ArrowRight, SlidersHorizontal, Image as ImageIcon, Wand2, RotateCw } from 'lucide-react';
import { downloadFile } from '../services/drive';
import { findSimilarPapers, SimilarityResult } from '../services/clustering';

interface PaperDetailsModalProps {
  paper: Paper;
  allPapers?: Paper[]; // Added to support similarity search
  onClose: () => void;
  onSelectPaper?: (paper: Paper) => void; // For navigating to similar papers
  googleToken?: string;
  onGenerateImage?: (paperId: string) => void;
}

const ConfidenceIndicator = ({ score }: { score?: number }) => {
  if (score === undefined || score === null) return null;
  const pct = Math.round(score * 100);

  let barColor = "bg-emerald-500";
  let textColor = "text-emerald-700";

  if (pct < 85) { barColor = "bg-blue-500"; textColor = "text-blue-700"; }
  if (pct < 70) { barColor = "bg-amber-500"; textColor = "text-amber-700"; }
  if (pct < 50) { barColor = "bg-rose-500"; textColor = "text-rose-700"; }

  return (
    <div className="flex items-center gap-2 ml-2 bg-white/60 px-1.5 py-0.5 rounded border border-slate-100" title={`Confidence: ${pct}%`}>
      <div className="w-10 h-1.5 bg-slate-200 rounded-full overflow-hidden">
        <div className={`h-full rounded-full transition-all duration-500 ${barColor}`} style={{ width: `${pct}%` }}></div>
      </div>
      <span className={`text-[10px] font-bold ${textColor}`}>{pct}%</span>
    </div>
  );
};

