  const [hasSearchedSimilar, setHasSearchedSimilar] = useState(false);
  const [similarityThreshold, setSimilarityThreshold] = useState(0.2); // Lowered default threshold to ensure results


  // Prevent background page scrolling while this modal is open
  React.useEffect(() => {
      const prevBodyOverflow = document.body.style.overflow;
      const prevHtmlOverflow = document.documentElement.style.overflow;

      document.body.style.overflow = 'hidden';
      document.documentElement.style.overflow = 'hidden';

      return () => {
          document.body.style.overflow = prevBodyOverflow;
          document.documentElement.style.overflow = prevHtmlOverflow;
      };
  }, []);

  // Reset similar results when paper changes
  React.useEffect(() => {
      setSimilarPapers([]);
      setHasSearchedSimilar(false);
      setSimilarityThreshold(0.2);
  }, [paper.id]);

  const handleFindSimilar = () => {
      if (!paper.embedding || !allPapers) return;
      // Get all results so we can filter locally with slider. -1 means "return all".
      const results = findSimilarPapers(paper, allPapers, -1);
      setSimilarPapers(results);
      setHasSearchedSimilar(true);
  };

  const handleImageGenerationClick = async () => {
      if (!onGenerateImage) return;
      setIsGeneratingImage(true);
      try {
          await onGenerateImage(paper.id);
      } finally {
          setIsGeneratingImage(false);
      }
  };

  const filteredSimilarPapers = useMemo(() => {
      // Filter by threshold and limit display to keep UI clean (e.g., max 10)
      return similarPapers.filter(p => p.score >= similarityThreshold);
  }, [similarPapers, similarityThreshold]);

  // Visualize Embedding Vector
  const embeddingVisualization = useMemo(() => {
    if (!paper.embedding || paper.embedding.length === 0) return null;

    // Downsample 1536 dimensions to ~64 bins for visualization
    const bins = 64;
    const dims = paper.embedding;
    const chunkSize = Math.ceil(dims.length / bins);
    const data = [];
    let maxAbs = 0;

    for (let i = 0; i < dims.length; i += chunkSize) {
        const chunk = dims.slice(i, i + chunkSize);
        // Calculate average activation for this chunk
        const val = chunk.reduce((acc, v) => acc + v, 0) / chunk.length;
        if (Math.abs(val) > maxAbs) maxAbs = Math.abs(val);
        data.push(val);
    }

    return (
        <div className="mt-6 bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
