                <div className="absolute top-1/2 left-0 right-0 h-px bg-slate-100 -z-10"></div>

                {data.map((v, i) => {
                    // Normalize height relative to max value in the set
                    const h = (Math.abs(v) / (maxAbs || 1)) * 100;
                    // Ensure minimal visibility
                    const displayH = Math.max(4, h);

                    return (
                        <div 
                            key={i} 
                            className={`flex-1 min-w-[2px] rounded-sm transition-all hover:opacity-80 hover:scale-y-110 ${v >= 0 ? 'bg-indigo-500' : 'bg-rose-400'}`} 
                            style={{ height: `${displayH}%` }}
                            title={`Bin ${i}: ${v.toFixed(4)}`}
                        />
                    );
                })}
            </div>
            <div className="flex justify-between mt-2 text-[9px] text-slate-400 uppercase font-bold tracking-wider">
                <span>Dim 0</span>
                <span>Activation Profile</span>
                <span>Dim {dims.length}</span>
            </div>
        </div>
    );
  }, [paper.embedding]);

  if (!paper) return null;

  const handleDownload = async () => {
      if (!googleToken || !paper.driveId) return;

      setIsDownloading(true);
      try {
          const buffer = await downloadFile(googleToken, paper.driveId);
          const blob = new Blob([buffer], { type: 'application/pdf' });
          const url = window.URL.createObjectURL(blob);
          const link = document.createElement('a');
          link.href = url;
          link.setAttribute('download', paper.filename);
          document.body.appendChild(link);
          link.click();
          link.remove();
          window.URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Download failed", e);
          alert("Failed to download file from Google Drive.");
      } finally {
          setIsDownloading(false);
      }
  };

  // Logic to determine arXiv URL
  const getArxivUrl = () => {
    if (paper.arxiv_id) {
        return `[local reference removed]`;
    }
    // Fallback: Try to find arXiv ID in DOI (e.g., 10.48550/arXiv.2205.12345)
    if (paper.doi && paper.doi.includes('arXiv')) {
        // extraction might vary, but usually it's 10.48550/arXiv.{ID}
        const parts = paper.doi.split('arXiv.');
        if (parts.length > 1) return `[local reference removed]`;
    }
    return null;
  };

  const arxivUrl = getArxivUrl();
  const needsImage = !paper.abstract || !paper.title || paper.generated_image;

  return (
