import React from 'react';
import { Loader2, CheckCircle, Circle, XCircle, ArrowLeft } from 'lucide-react';
import { ProcessingStatus } from '../types';

interface ProcessingLogProps {
  currentStatus: ProcessingStatus;
  logs: string[];
  progress: number;
  onStop: () => void;
  onReturn?: () => void;
}

const steps = [
  { id: ProcessingStatus.EXTRACTING, label: 'PDF Extraction' },
  { id: ProcessingStatus.EMBEDDING, label: 'Embedding Generation' },
  { id: ProcessingStatus.CLUSTERING, label: 'Topic Clustering' },
  { id: ProcessingStatus.REVIEW_WAIT, label: 'Taxonomy Review' },
  { id: ProcessingStatus.CLASSIFYING, label: 'Final Classification' }
];

export const ProcessingLog: React.FC<ProcessingLogProps> = ({ currentStatus, logs, progress, onStop, onReturn }) => {
  const getCurrentStepIndex = () => {
    const idx = steps.findIndex(s => s.id === currentStatus);
    return idx === -1 ? (currentStatus === ProcessingStatus.COMPLETED ? steps.length : 0) : idx;
  };

  const currentStepIdx = getCurrentStepIndex();
  const isFinished = currentStatus === ProcessingStatus.COMPLETED || currentStatus === ProcessingStatus.FAILED;

  return (
    <div className="grid grid-cols-3 gap-6 h-[calc(100vh-140px)]">
      {/* Left: Progress Steps */}
      <div className="col-span-1 bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col">
        <h3 className="text-lg font-semibold mb-6">Pipeline Progress</h3>
        <div className="space-y-6 flex-1 overflow-y-auto">
          {steps.map((step, idx) => {
            const isCompleted = idx < currentStepIdx;
            const isCurrent = idx === currentStepIdx;

            return (
              <div key={step.id} className="flex items-center gap-3">
                {isCompleted ? (
                  <CheckCircle className="text-green-500 shrink-0" size={24} />
                ) : isCurrent ? (
                  <Loader2 className="text-blue-500 animate-spin shrink-0" size={24} />
                ) : (
                  <Circle className="text-slate-300 shrink-0" size={24} />
                )}
                <div>
                  <p className={`font-medium ${isCurrent ? 'text-blue-600' : isCompleted ? 'text-slate-900' : 'text-slate-400'}`}>
                    {step.label}
                  </p>
                  {isCurrent && (
                    <p className="text-xs text-slate-500 mt-1">{Math.round(progress)}% Complete</p>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <div className="mt-6 border-t border-slate-100 pt-6">
             {!isFinished ? (
                <button 
                    onClick={onStop}
                    className="w-full flex items-center justify-center gap-2 px-4 py-2.5 bg-red-50 text-red-600 border border-red-200 rounded-lg hover:bg-red-100 font-medium transition-colors"
                >
                    <XCircle size={18} /> Stop Processing
                </button>
             ) : (
                <button 
                    onClick={onReturn}
                    className="w-full flex items-center justify-center gap-2 px-4 py-2.5 bg-slate-50 text-slate-700 border border-slate-200 rounded-lg hover:bg-slate-100 font-medium transition-colors"
                >
                    <ArrowLeft size={18} /> Back to Dashboard
                </button>
             )}
        </div>
      </div>

      {/* Right: Terminal/Logs */}
      <div className="col-span-2 bg-slate-900 p-6 rounded-xl shadow-lg text-slate-300 font-mono text-sm overflow-hidden flex flex-col">
        <div className="flex items-center gap-2 mb-4 pb-4 border-b border-slate-700">
            <div className="w-3 h-3 rounded-full bg-red-500"></div>
            <div className="w-3 h-3 rounded-full bg-yellow-500"></div>
            <div className="w-3 h-3 rounded-full bg-green-500"></div>
            <span className="ml-2 text-xs text-slate-500">system_logs.txt</span>
        </div>
        <div className="flex-1 overflow-y-auto space-y-2 scrollbar-thin scrollbar-thumb-slate-700">
            {logs.map((log, i) => (
                <div key={i} className="break-words">
                    <span className="text-slate-500">[{new Date().toLocaleTimeString()}]</span>{' '}
                    <span className={log.includes('Error') || log.includes('failed') ? 'text-red-400' : log.includes('>>>') ? 'text-yellow-400' : 'text-slate-300'}>{log}</span>
                </div>
            ))}
             {!isFinished && <div className="animate-pulse">_</div>}
        </div>
      </div>
    </div>
  );
};

