export const TaxonomyVisualizer: React.FC<TaxonomyVisualizerProps> = ({ taxonomy, allPapers, onSelectPaper, onClose }) => {
  const [scale, setScale] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging) {
      setPosition({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      });
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  // Recursive function to build tree
  const renderTree = (
      node: any, 
      level: NodeLevel, 
      getChildren: (n: any) => any[],
      getNextLevel: (l: NodeLevel) => NodeLevel
  ) => {
      const children = getChildren(node);

      const childNodes = children?.map(child => 
          renderTree(
              child, 
              getNextLevel(level), 
              (n) => n.mid_categories || n.fine_categories || [], 
              (l) => l === 'broad' ? 'mid' : 'fine'
          )
      );

      return (
          <TreeNode 
            key={node.id}
            label={node.name}
            description={node.description}
            count={node.paper_count}
            level={level}
            childNodes={childNodes}
            paperIds={node.paper_ids}
            allPapers={allPapers}
            onSelectPaper={onSelectPaper}
          />
      );
  };

  const rootNode = {
      id: 'root',
      name: 'Research Corpus',
      description: 'All processed research papers organized by topic.',
      paper_count: taxonomy.hierarchy.broad.reduce((acc, b) => acc + b.paper_count, 0),
      // Fake structure to kickstart recursion
      children: taxonomy.hierarchy.broad,
      // Collect all paper IDs for the root
      paper_ids: taxonomy.hierarchy.broad.flatMap(b => b.paper_ids || [])
  };

  return (
    <div className="fixed inset-0 z-50 bg-slate-50 flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center shadow-sm z-10">
         <div className="flex items-center gap-3">
            <div className="bg-blue-100 p-2 rounded-lg text-blue-600">
                <GitBranch size={20} />
            </div>
            <div>
                <h2 className="text-lg font-bold text-slate-900">Taxonomy Map</h2>
                <p className="text-xs text-slate-500">Interactive hierarchical visualization of research topics</p>
            </div>
         </div>
         <div className="flex items-center gap-4">
            <div className="flex items-center bg-slate-100 rounded-lg p-1 border border-slate-200">
                <button onClick={() => setScale(s => Math.max(0.5, s - 0.1))} className="p-1.5 hover:bg-white hover:shadow-sm rounded text-slate-600"><ZoomOut size={18} /></button>
                <span className="text-xs font-mono w-12 text-center text-slate-500">{Math.round(scale * 100)}%</span>
                <button onClick={() => setScale(s => Math.min(2, s + 0.1))} className="p-1.5 hover:bg-white hover:shadow-sm rounded text-slate-600"><ZoomIn size={18} /></button>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors">
                <X size={24} />
            </button>
         </div>
      </div>

      {/* Canvas */}
      <div 
        className="flex-1 overflow-hidden relative bg-slate-50 cursor-move select-none"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
         <div className="absolute top-4 left-4 z-0 pointer-events-none opacity-50 text-slate-400 flex items-center gap-2 text-sm">
            <Move size={16} /> Drag to pan
         </div>

         <div 
            ref={containerRef}
            className="absolute origin-top-left transition-transform duration-75 ease-out"
            style={{ 
                transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`,
                padding: '100px' // Padding to ensure not cut off initially
            }}
         >
            {renderTree(
                rootNode, 
                'root', 
                (n) => n.children || taxonomy.hierarchy.broad, 
                (l) => 'broad'
            )}
         </div>
      </div>
    </div>
  );
};

