// Calculate cosine similarity between two vectors
export function cosineSimilarity(a: number[], b: number[]): number {
  let dotProduct = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < a.length; i++) {
    dotProduct += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }

  // Guard against zero vectors to avoid NaN
  if (normA === 0 || normB === 0) return 0;

  return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
}

export interface SimilarityResult {
  paper: Paper;
  score: number;
}

export function findSimilarPapers(targetPaper: Paper, allPapers: Paper[], topK: number = 5, minScore: number = 0): SimilarityResult[] {
  if (!targetPaper.embedding || targetPaper.embedding.length === 0) return [];

  const results: SimilarityResult[] = [];

  for (const p of allPapers) {
    // Skip self and papers without embeddings
    if (p.id === targetPaper.id || !p.embedding || p.embedding.length === 0) continue;

    const score = cosineSimilarity(targetPaper.embedding, p.embedding);
    if (score >= minScore) {
        results.push({ paper: p, score });
    }
  }

  // Sort descending by score
  results.sort((a, b) => b.score - a.score);

  // If topK is positive, slice. If <= 0 (e.g. -1), return all.
  if (topK > 0) {
      return results.slice(0, topK);
  }
  return results;
}

// Simple K-Means implementation for client-side demo
// Real spec asks for HDBSCAN which is complex in pure JS without WASM.
// We will simulate hierarchical clustering by recursive K-Means.
export function performClustering(papers: Paper[], k: number): number[] {
  // Returns array of cluster indices for each paper
  if (papers.length === 0) return [];

  // Initialize centroids randomly
  let centroids = papers.slice(0, k).map(p => p.embedding!);
  let assignments = new Array(papers.length).fill(0);
  let changed = true;
  let iterations = 0;

  while (changed && iterations < 20) {
    changed = false;
    // Assign
    for (let i = 0; i < papers.length; i++) {
      let maxSim = -1;
      let bestCluster = 0;
      for (let c = 0; c < k; c++) {
        if (!centroids[c]) continue;
        const sim = cosineSimilarity(papers[i].embedding!, centroids[c]);
        if (sim > maxSim) {
          maxSim = sim;
          bestCluster = c;
        }
      }
      if (assignments[i] !== bestCluster) {
        assignments[i] = bestCluster;
        changed = true;
      }
    }

    // Update centroids
    const newCentroids = new Array(k).fill(null).map(() => new Array(papers[0].embedding!.length).fill(0));
    const counts = new Array(k).fill(0);

    for (let i = 0; i < papers.length; i++) {
        const cluster = assignments[i];
        counts[cluster]++;
        for(let j=0; j< papers[i].embedding!.length; j++) {
            newCentroids[cluster][j] += papers[i].embedding![j];
        }
    }

    for (let c=0; c<k; c++) {
        if (counts[c] > 0) {
            for(let j=0; j< newCentroids[c].length; j++) {
                newCentroids[c][j] /= counts[c];
            }
            centroids[c] = newCentroids[c];
        }
    }
    iterations++;
  }

  return assignments;
}

