import { GoogleGenAI } from "@google/genai";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
  }

  async generatePaperImage(title: string, summary: string): Promise<string> {
    // Construct a prompt that focuses on abstract visualization of the research topic
    const prompt = `Create a high-quality, minimalist, abstract cover image representing this research paper.

    Paper Title: ${title || "Untitled Scientific Research"}
    Key Topic Summary: ${summary ? summary.slice(0, 400) : "Advanced scientific analysis and data processing."}

    Style: Digital art, geometric, clean, professional, data-driven visualization. No text. Based on and relevant to the title and topic summary.`;

    try {
        // Use gemini-2.5-flash-image as default for image generation
        const response = await this.ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [{ text: prompt }]
            },
            config: {
                imageConfig: {
                    aspectRatio: "16:9"
                }
            }
        });

        if (response.candidates && response.candidates[0].content && response.candidates[0].content.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData) {
                    return `data:image/png;base64,${part.inlineData.data}`;
                }
            }
        }
        throw new Error("Model did not return an image part.");
    } catch (error) {
        console.error("Gemini Image Generation Error:", error);
        throw error;
    }
  }
}

