// --- Helpers (robust parsing for Responses API + schema variations) ---

const stripCodeFences = (s: string) => {
  const trimmed = (s || '').trim();
  if (!trimmed) return '';
  // ```json ... ``` or ``` ... ```
  if (trimmed.startsWith('```')) {
    const lines = trimmed.split('\n');
    // Remove first line (``` or ```json)
    const withoutFirst = lines.slice(1);
    // Remove last line if it's ```
    if (withoutFirst.length && withoutFirst[withoutFirst.length - 1].trim().startsWith('```')) {
      withoutFirst.pop();
    }
    return withoutFirst.join('\n').trim();
  }
  return trimmed;
};

const extractFirstJsonBlock = (s: string) => {
  const t = stripCodeFences(s);
  if (!t) return '';
  const firstBrace = t.indexOf('{');
  const firstBracket = t.indexOf('[');
  const start = firstBrace === -1 ? firstBracket : (firstBracket === -1 ? firstBrace : Math.min(firstBrace, firstBracket));
  if (start === -1) return t;
  const endBrace = t.lastIndexOf('}');
  const endBracket = t.lastIndexOf(']');
  const end = Math.max(endBrace, endBracket);
  if (end === -1 || end <= start) return t.slice(start);
  return t.slice(start, end + 1);
};

const coerceStringArray = (v: any): string[] | undefined => {
  if (!v) return undefined;
  if (Array.isArray(v)) return v.map(x => String(x).trim()).filter(Boolean);
  if (typeof v === 'string') {
    // Split on common separators if model returns a single string
    return v.split(/\s*[,;\n]\s*/g).map(x => x.trim()).filter(Boolean);
  }
  return undefined;
};

const normalizeMetadata = (raw: any): Partial<PaperMetadata> => {
  if (!raw || typeof raw !== 'object') return {};
  // Support schema drift / casing variants
  const title = raw.title ?? raw.Title;
  const authors = raw.authors ?? raw.Authors;
  const publish_date = raw.publish_date ?? raw.published_date ?? raw.publication_date ?? raw.PublishedDate ?? raw['Publication Date'];
  const doi = raw.doi ?? raw.DOI;
  const arxiv_id = raw.arxiv_id ?? raw.arxivId ?? raw.ArxivID ?? raw.arXiv_id ?? raw.arXivId;
  const abstract = raw.abstract ?? raw.Abstract;
  const summary = raw.summary ?? raw.Summary;
  const notes = raw.notes ?? raw.extraction_notes ?? raw.extractionNotes ?? raw.Notes;

  return {
    title: typeof title === 'string' ? title.trim() : undefined,
    authors: coerceStringArray(authors),
    publish_date: typeof publish_date === 'string' ? publish_date.trim() : undefined,
    doi: typeof doi === 'string' ? doi.trim() : (doi === null ? undefined : undefined),
    arxiv_id: typeof arxiv_id === 'string' ? arxiv_id.trim() : (arxiv_id === null ? undefined : undefined),
    abstract: typeof abstract === 'string' ? abstract.trim() : undefined,
    summary: typeof summary === 'string' ? summary.trim() : undefined,
    extraction_notes: typeof notes === 'string' ? notes.trim() : undefined,
  };
};

const normalizeTaxonomyLabel = (raw: any) => {
  if (!raw || typeof raw !== 'object') return { category_name: '', description: '', key_characteristics: [] as string[] };
  const category_name = raw.category_name ?? raw.categoryName ?? raw.name ?? raw.category ?? raw.CategoryName;
  const description = raw.description ?? raw.Description ?? '';
  const key_characteristics = raw.key_characteristics ?? raw.keyCharacteristics ?? raw.characteristics ?? raw.traits;
  return {
    category_name: typeof category_name === 'string' ? category_name.trim() : String(category_name ?? '').trim(),
    description: typeof description === 'string' ? description.trim() : String(description ?? '').trim(),
    key_characteristics: (Array.isArray(key_characteristics) ? key_characteristics : []).map((x: any) => String(x).trim()).filter(Boolean),
  };
};

const normalizeClassification = (raw: any) => {
  if (!raw || typeof raw !== 'object') return {};
  return {
    mid_category: (raw.mid_category ?? raw.midCategory ?? '').toString().trim(),
    fine_category: (raw.fine_category ?? raw.fineCategory ?? '').toString().trim(),
    reasoning: (raw.reasoning ?? '').toString().trim(),
    mid_confidence: typeof raw.mid_confidence === 'number' ? raw.mid_confidence : (typeof raw.midConfidence === 'number' ? raw.midConfidence : undefined),
    fine_confidence: typeof raw.fine_confidence === 'number' ? raw.fine_confidence : (typeof raw.fineConfidence === 'number' ? raw.fineConfidence : undefined),
  };
};

const getResponsesOutputText = (data: any): string => {
  if (!data) return '';
  if (typeof data.output_text === 'string' && data.output_text.trim()) return data.output_text;

  // Fallback: walk output -> message -> content -> output_text
  const out = Array.isArray(data.output) ? data.output : [];
  const msg = out.find((i: any) => i?.type === 'message') ?? out[0];
  const content = Array.isArray(msg?.content) ? msg.content : [];
  const pieces = content
    .map((c: any) => (typeof c?.text === 'string' ? c.text : ''))
    .filter(Boolean);
  return pieces.join('');
};
