  private async callResponse<T>(input: string, instruction: string, options: { json?: boolean, schema?: any, name?: string } = { json: true }): Promise<T> {
    // IMPORTANT: callers often pass { schema, name } without a json flag.
    // Merge defaults so json remains true unless explicitly set to false.
    const opts = { json: true, ...options };

    // Determine the format object
    let formatObj: any;
    if (opts.schema) {
      formatObj = {
        type: 'json_schema',
        name: opts.name,
        schema: opts.schema,
        strict: true,
      };
    } else if (opts.json) {
      formatObj = { type: 'json_object' };
    }
    const body: any = {
      model: this.model,
      instructions: instruction,
      input,
      reasoning: { effort: 'low' },
      text: { 
        verbosity: 'low',
        // Correctly nest the format configuration under the text object
        ...(formatObj ? { format: formatObj } : {})
      },
    };

    const res = await fetch('https://api.openai.com/v1/responses', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.apiKey}`
      },
      body: JSON.stringify(body),
    });

    if (!res.ok) throw new Error((await res.json()).error?.message || 'OpenAI API Error');

    const data = await res.json();
    console.log("OpenAI Response:", JSON.stringify(data, null, 2));

    const text = getResponsesOutputText(data);

    if (opts.json === false && !opts.schema) return text as unknown as T;

    const candidate = extractFirstJsonBlock(text);
    try {
      return JSON.parse(candidate) as T;
    } catch (e) {
      const preview = (candidate || text || '').slice(0, 500);
      throw new Error(`Failed to parse JSON from model response. Preview: ${preview}`);
