import * as pdfjsLib from 'pdfjs-dist';
import { createWorker } from 'tesseract.js';

// Use the mjs worker for module compatibility with the ESM build of PDF.js
// We use unpkg to ensure we get the correct build artifact (.mjs) for the specific version
pdfjsLib.GlobalWorkerOptions.workerSrc = `[local reference removed]`;

async function performOcr(pdf: any, maxPages: number): Promise<string> {
  console.log("Initializing Tesseract OCR worker...");
  const worker = await createWorker('eng');
  let fullText = '';

  try {
    for (let i = 1; i <= maxPages; i++) {
      try {
        const page = await pdf.getPage(i);
        // Scale 1.5 provides a good balance between speed and OCR accuracy
        const viewport = page.getViewport({ scale: 1.5 }); 

        const canvas = document.createElement('canvas');
        canvas.height = viewport.height;
        canvas.width = viewport.width;

        const context = canvas.getContext('2d');
        if (!context) continue;

        await page.render({ canvasContext: context, viewport: viewport }).promise;

        // Tesseract.js recognizes text from the canvas
        const { data: { text } } = await worker.recognize(canvas);
        fullText += text + '\n';

        // Clear canvas memory
        canvas.width = 0;
        canvas.height = 0;
      } catch (pageError) {
        console.warn(`OCR error on page ${i}:`, pageError);
      }
    }
  } finally {
    await worker.terminate();
  }
  return fullText;
}

export async function extractTextFromPdf(file: File): Promise<string> {
  const arrayBuffer = await file.arrayBuffer();

  try {
    // Load document
    const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer,standardFontDataUrl: `[local reference removed]` });
    const pdf = await loadingTask.promise;

    let fullText = '';
    // Spec says "Max pages to process: 50".
    const maxPages = Math.min(pdf.numPages, 50);

    for (let i = 1; i <= maxPages; i++) {
      try {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          const pageText = textContent.items.map((item: any) => item.str).join(' ');
          fullText += pageText + '\n';
      } catch (e) {
          console.warn(`Error extracting page ${i}`, e);
      }
    }

    // Spec: "If text_quality_score < 0.5, Stage 3: OCR fallback"
    // We use length < 100 as a proxy for poor extraction quality (e.g. scanned PDFs)
    if (fullText.trim().length < 100) {
        console.warn("Low text extraction confidence (length < 100 chars). Triggering OCR fallback.");
        try {
            const ocrText = await performOcr(pdf, maxPages);
            // Only replace if OCR found significantly more text
            if (ocrText.trim().length > fullText.trim().length) {
                console.log("OCR extraction successful, replacing text layer content.");
                return ocrText;
            }
        } catch (ocrError) {
            console.error("OCR fallback failed:", ocrError);
        }
    }

    return fullText;
  } catch (error: any) {
    // Provide clearer error messages for common PDF.js issues
    if (error.name === 'MissingPDFException') {
        throw new Error("Invalid PDF file data.");
    }
    if (error.message && error.message.includes("fake worker")) {
        throw new Error("PDF Worker initialization failed. This is often due to a version mismatch or network block on the CDN worker file.");
    }
    throw error;
  }
}

import { Paper } from '../types';

const DB_NAME = 'ResearchAI_DB';
const DB_VERSION = 1;
const STORE_NAME = 'papers';

// Open DB helper
const openDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
  });
};

export const savePapersToDB = async (papers: Paper[]) => {
  const db = await openDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error);

    // Clear and rewrite to ensure exact state sync
    store.clear().onsuccess = () => {
        papers.forEach(paper => {
            // Strip fileObj as it generally cannot be persisted across sessions reliably
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            const { fileObj, ...rest } = paper;
            store.put(rest);
        });
    };
  });
};

export const loadPapersFromDB = async (): Promise<Paper[]> => {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const clearPapersDB = async () => {
    const db = await openDB();
    return new Promise<void>((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.clear();
        request.onsuccess = () => resolve();
        request.onerror = () => reject(request.error);
    });
};

